widget_def.init:
var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
                var xc1v2=R1+xc2v2-R2-1;
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1v2-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2v2,cc=B*B+xc2v2*xc2v2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2v2);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  var gc=255-Math.round(15*y1);
                  rayLine(xmin,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}
            }

            /* ── Foyer (convergents) ── */
            if(TL.mode===0||TL.mode===2||TL.mode===5){
              /* Lensmaker grossière */
              var f_approx;
              if(TL.mode===0){
                f_approx=1/((N-1)*(2/R1));
              } else if(TL.mode===2){
                f_approx=R1/(N-1);
              } else {
                f_approx=1/((N-1)*Math.abs(1/R1-1/R2));
              }
              if(f_approx>0&&f_approx<80){
                ctx.beginPath();
                ctx.arc(px(f_approx),py(0),4,0,PI*2);
                ctx.fillStyle='rgba(255,210,50,0.9)';
                ctx.fill();
                ctx.fillStyle='rgba(255,210,50,0.7)';
                ctx.font='8px system-ui';
                ctx.textAlign='center';
                ctx.fillText('F\'',px(f_approx),py(0)-7);
              }
            }

            /* ── Label mode ── */
            ctx.fillStyle='rgba(255,255,255,.3)';
            ctx.font='bold 9px system-ui';
            ctx.textAlign='right';
            ctx.fillText(TL.modes[TL.mode].label,W-padR-3,padT+11);

            /* ── Stats ── */
            var statsEl=document.getElementById('tl-stats');
            var f_v='—', V_v='—', P_v='—';
            if(TL.mode===0){
              var f2=1/((N-1)*(2/R1-TL.d*(N-1)/(N*R1*R1)));
              f_v=isFinite(f2)?Math.round(f2)+' u':'∞';
              P_v=isFinite(f2)?(1000/f2).toFixed(1)+' δ':'—';
            } else if(TL.mode===1||TL.mode===2){
              var fv=(TL.mode===1?R2:R1)/(N-1);
              f_v=Math.round(fv)+' u'; P_v=(1000/fv).toFixed(1)+' δ';
            }
            statsEl.innerHTML=
              '<div style="background:rgba(94,231,223,.08);border:1px solid rgba(94,231,223,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Focale f\'</div>'
              +'<div style="font-size:15px;font-weight:800;color:#5ee7df;font-variant-numeric:tabular-nums">'+f_v+'</div></div>'
              +'<div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Puissance</div>'
              +'<div style="font-size:15px;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums">'+P_v+'</div></div>'
              +'<div style="background:rgba(247,168,216,.08);border:1px solid rgba(247,168,216,.2);border-radius:7px;padding:7px 10px;text-align:center">'
              +'<div style="font-size:9px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:.06em;margin-bottom:3px">Indice n</div>'
              +'<div style="font-size:15px;font-weight:800;color:#f7a8d8;font-variant-numeric:tabular-nums">'+N.toFixed(2)+'</div></div>';
          }

          /* resize observer */
          if(window.ResizeObserver){
            var _ro=new ResizeObserver(function(){tlDraw();});
            _ro.observe(cv);
          }

          /* Activer le _needs3D pour Optique */
          var _svOpt=document.getElementById('sheetViewer');
          if(_svOpt){_svOpt.style.width='';_svOpt.style.minWidth='';}
          var _siOpt=document.getElementById('sheetInfo');
          if(_siOpt){_siOpt.style.display='';_siOpt.style.flex='';}

          tlInit();

var cv=container.querySelector('#tl-cv');
var root=container.querySelector('#tl-root');
/* ── State ── */
          var TL={
            mode:0,nb:5,
            R1:20,R2:30,N:1.5,
            d:10.5,
            modes:[
              {label:'Biconvexe',   R1:{min:20,max:125,v:40},  R2:{min:20,max:125,v:40},  showR1:1,showR2:1, dia:1},
              {label:'Plan-cvx 1',  R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:1},
              {label:'Plan-cvx 2',  R1:{min:15,max:55,v:30},   R2:null,                   showR1:1,showR2:0, dia:1},
              {label:'Biconcave',   R1:{min:22,max:55,v:30},   R2:{min:22,max:55,v:30},   showR1:1,showR2:1, dia:0},
              {label:'Plan-cve',    R1:null,                    R2:{min:12,max:55,v:28},   showR1:0,showR2:1, dia:0},
              {label:'Mén. cvgt',   R1:{min:15,max:55,v:20},   R2:{min:23,max:65,v:30},   showR1:1,showR2:1, dia:1},
              {label:'Mén. dvgt',   R1:{min:23,max:65,v:60},   R2:{min:17,max:55,v:20},   showR1:1,showR2:1, dia:0},
            ]
          };

          /* ── Tabs ── */
          var tabsEl=document.getElementById('tl-tabs');
          TL.modes.forEach(function(mo,i){
            var btn=document.createElement('button');
            btn.textContent=mo.label;
            btn.style.cssText='background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);'
              +'border-radius:6px;padding:4px 10px;cursor:pointer;font-size:10px;font-family:inherit;transition:all .15s';
            btn.addEventListener('click',function(){TL.mode=i;tlInit();});
            tabsEl.appendChild(btn);
          });

          function tlHighlightTab(){
            tabsEl.querySelectorAll('button').forEach(function(b,i){
              var act=i===TL.mode;
              b.style.background=act?'rgba(94,231,223,.18)':'rgba(255,255,255,.07)';
              b.style.borderColor=act?'#5ee7df':'rgba(255,255,255,.1)';
              b.style.color=act?'#5ee7df':'rgba(255,255,255,.5)';
              b.style.fontWeight=act?'700':'400';
            });
          }

          /* ── Controls ── */
          var r1In=document.getElementById('tl-r1'),r2In=document.getElementById('tl-r2'),nIn=document.getElementById('tl-n');
          var r1VEl=document.getElementById('tl-r1-v'),r2VEl=document.getElementById('tl-r2-v'),nVEl=document.getElementById('tl-n-v');
          var r1Row=document.getElementById('tl-r1-row'),r2Row=document.getElementById('tl-r2-row');
          var nbEl=document.getElementById('tl-nb');
          var bmBtn=document.getElementById('tl-bm'),bpBtn=document.getElementById('tl-bp');

          bmBtn.addEventListener('click',function(){if(TL.nb>2)TL.nb--;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          bpBtn.addEventListener('click',function(){if(TL.nb<6)TL.nb++;nbEl.textContent=TL.nb;bmBtn.disabled=TL.nb<=2;bpBtn.disabled=TL.nb>=6;tlDraw();});
          r1In.addEventListener('input',function(){TL.R1=parseFloat(r1In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          r2In.addEventListener('input',function(){TL.R2=parseFloat(r2In.value);tlCheckMeniscus();tlLabels();tlDraw();});
          nIn.addEventListener('input',function(){TL.N=parseInt(nIn.value)/100;tlLabels();tlDraw();});

          function tlCheckMeniscus(){
            if(TL.mode===5&&TL.R1>TL.R2-5){TL.R2=TL.R1+5;r2In.value=TL.R2;}
            if(TL.mode===6&&TL.R1<TL.R2+5){TL.R1=TL.R2+5;r1In.value=TL.R1;}
          }

          function tlLabels(){
            var mo=TL.modes[TL.mode];
            r1Row.style.display=mo.showR1?'':'none';
            r2Row.style.display=mo.showR2?'':'none';
            if(mo.showR1) r1VEl.textContent=TL.R1.toFixed(1);
            if(mo.showR2) r2VEl.textContent=TL.R2.toFixed(1);
            nVEl.textContent=TL.N.toFixed(2);
            nbEl.textContent=TL.nb;
          }

          function tlInit(){
            tlHighlightTab();
            var mo=TL.modes[TL.mode];
            if(mo.R1){r1In.min=mo.R1.min;r1In.max=mo.R1.max;r1In.value=mo.R1.v;TL.R1=mo.R1.v;}
            if(mo.R2){r2In.min=mo.R2.min;r2In.max=mo.R2.max;r2In.value=mo.R2.v;TL.R2=mo.R2.v;}
            tlLabels();tlDraw();
          }

          /* ══════════════════════════════════════════════════
             CANVAS DRAWING — redesigned
          ══════════════════════════════════════════════════ */
          var cv=document.getElementById('tl-cv');
          var PI=Math.PI;
function tlDraw(){
            var W=cv.offsetWidth||300;
            var H=Math.round(W*0.52);
            cv.width=W; cv.height=H;
            var ctx=cv.getContext('2d');

            /* coordonnée monde → pixel */
            var mo=TL.modes[TL.mode];
            var xmin,xmax,xdia;
            switch(TL.mode){
              case 0: xmin=-20;xmax=60;xdia=-15;break;
              case 1: xmin=-10;xmax=70;xdia=-5;break;
              case 2: xmin=-10;xmax=70;xdia=-5;break;
              case 3: xmin=-60;xmax=20;xdia= 0;break;
              case 4: xmin=-60;xmax=20;xdia= 0;break;
              case 5: xmin=-10;xmax=70;xdia=-5;break;
              case 6: xmin=-60;xmax=20;xdia= 0;break;
            }
            var ymin=-20,ymax=20;
            var padL=8,padR=8,padT=8,padB=8;
            var kx=(W-padL-padR)/(xmax-xmin);
            var ky=(H-padT-padB)/(ymax-ymin);
            function px(x){return padL+kx*(x-xmin);}
            function py(y){return padT+ky*(ymax-y);}

            /* ── Background ── */
            ctx.fillStyle='#0a0c12';
            ctx.fillRect(0,0,W,H);

            /* ── Subtle grid ── */
            ctx.strokeStyle='rgba(255,255,255,.04)';
            ctx.lineWidth=1;
            for(var gx=Math.ceil(xmin/10)*10;gx<=xmax;gx+=10){
              ctx.beginPath();ctx.moveTo(px(gx),padT);ctx.lineTo(px(gx),H-padB);ctx.stroke();
            }
            for(var gy=-20;gy<=20;gy+=5){
              ctx.beginPath();ctx.moveTo(padL,py(gy));ctx.lineTo(W-padR,py(gy));ctx.stroke();
            }

            /* ── Optical axis ── */
            ctx.strokeStyle='rgba(255,255,255,.15)';
            ctx.lineWidth=1;
            ctx.setLineDash([6,4]);
            ctx.beginPath();ctx.moveTo(padL,py(0));ctx.lineTo(W-padR,py(0));ctx.stroke();
            ctx.setLineDash([]);

            /* ── Tick marks on axis ── */
            ctx.fillStyle='rgba(255,255,255,.25)';
            ctx.font='7px system-ui';
            ctx.textAlign='center';
            for(var tx=Math.ceil(xmin/10)*10;tx<=xmax;tx+=10){
              ctx.fillStyle='rgba(255,255,255,.2)';
              ctx.beginPath();ctx.moveTo(px(tx),py(0)-3);ctx.lineTo(px(tx),py(0)+3);ctx.stroke();
              if(tx!==0){ctx.fillText(tx,px(tx),py(0)+11);}
            }

            var d=TL.d, R1=TL.R1, R2=TL.R2, N=TL.N;

            /* ─────────────────────────────────────────────────
               Helper : draw a circular arc on canvas
               cx,cy = centre cercle (monde), R = rayon,
               a1,a2 = angles départ/fin (rad), ccw
            ───────────────────────────────────────────────── */
            function arc(cx,cy,R,a1,a2,ccw){
              ctx.arc(px(cx),py(cy),R*kx,a1,a2,ccw);
            }

            /* ─────────────────────────────────────────────────
               LENTILLE — dessin vectoriel propre
            ───────────────────────────────────────────────── */
            ctx.save();

            /* Gradient verre */
            var grd=ctx.createLinearGradient(px(-5),0,px(5),0);
            grd.addColorStop(0,  'rgba(100,210,255,0.12)');
            grd.addColorStop(0.5,'rgba(160,240,255,0.22)');
            grd.addColorStop(1,  'rgba(100,210,255,0.10)');

            function drawLens(){
              ctx.beginPath();
              /* Surface sphérique échantillonnée en y de ylo à yhi.
                 vx=sommet sur l'axe ; bulge=+1 bombe vers +x, -1 vers -x.
                 Cercle (x-cx)^2+y^2=R^2 avec cx=vx-bulge*R, racine côté sommet. */
              function surf(vx,R,bulge,ylo,yhi){
                var cx=vx-bulge*R, n=48, first=true;
                for(var i=0;i<=n;i++){
                  var y=ylo+(yhi-ylo)*i/n;
                  var r2=R*R-y*y; if(r2<0) r2=0;
                  var x=cx+bulge*Math.sqrt(r2);
                  if(first){ ctx.lineTo(px(x),py(y)); first=false; }
                  else ctx.lineTo(px(x),py(y));
                }
              }
              switch(TL.mode){
                case 0:{ /* biconvexe */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf( 3,R2,+1, d,-d);           /* face D convexe */
                  ctx.closePath(); break;}
                case 1:{ /* plan-convexe : G plane, D convexe */
                  ctx.moveTo(px(-1.5),py(-d));
                  ctx.lineTo(px(-1.5),py(d));
                  surf(3,R2,+1,d,-d);
                  ctx.closePath(); break;}
                case 2:{ /* convexe-plan : G convexe, D plane */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);
                  ctx.lineTo(px(1.5),py(d));
                  ctx.lineTo(px(1.5),py(-d));
                  ctx.closePath(); break;}
                case 3:{ /* biconcave : faces creusées vers le centre */
                  ctx.moveTo(px(-1.5),py(-d));    /* coin bas gauche (bord épais) */
                  surf(-1.5,R1,+1,-d,d);          /* face G concave (creux vers +x) */
                  surf( 1.5,R2,-1, d,-d);         /* face D concave (creux vers -x) */
                  ctx.closePath(); break;}
                case 4:{ /* plan-concave : G plane, D concave */
                  ctx.moveTo(px(-3),py(-d));
                  ctx.lineTo(px(-3),py(d));
                  surf(1.5,R2,-1,d,-d);           /* face D concave */
                  ctx.closePath(); break;}
                case 5:{ /* ménisque convergent : G convexe, D concave (R1<R2) */
                  ctx.moveTo(px(-3-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-3,R1,-1,-d,d);            /* face G convexe */
                  surf(-1,R2,-1, d,-d);           /* face D concave (même sens, moins courbée) */
                  ctx.closePath(); break;}
                case 6:{ /* ménisque divergent : G convexe, D concave (R1>R2) */
                  ctx.moveTo(px(-1-(R1-Math.sqrt(R1*R1-d*d))),py(-d));
                  surf(-1,R1,-1,-d,d);            /* face G convexe (peu courbée) */
                  surf(-3,R2,-1, d,-d);           /* face D concave (plus courbée) */
                  ctx.closePath(); break;}
              }
            }

            drawLens();
            ctx.fillStyle=grd;
            ctx.fill();

            /* Contour lentille */
            ctx.strokeStyle='rgba(100,220,255,0.55)';
            ctx.lineWidth=1.5;
            drawLens();
            ctx.stroke();
            ctx.restore();

            /* ── Diaphragme (modes convergents) ── */
            if(mo.dia){
              ctx.strokeStyle='rgba(255,80,80,0.7)';
              ctx.lineWidth=3;
              var diaX=xdia;
              ctx.beginPath();ctx.moveTo(px(diaX),py(-17));ctx.lineTo(px(diaX),py(-1.5*TL.nb));ctx.stroke();
              ctx.beginPath();ctx.moveTo(px(diaX),py(17));ctx.lineTo(px(diaX),py(1.5*TL.nb));ctx.stroke();
            }

            /* ═══════════════════════════════════════════════
               TRACÉ DES RAYONS
            ═══════════════════════════════════════════════ */
            function rayLine(x1,y1,x2,y2,clr,dash){
              ctx.strokeStyle=clr;
              ctx.lineWidth=1.2;
              if(dash)ctx.setLineDash([5,4]);else ctx.setLineDash([]);
              ctx.beginPath();ctx.moveTo(px(x1),py(y1));ctx.lineTo(px(x2),py(y2));ctx.stroke();
              ctx.setLineDash([]);
            }
            function rayColor(y){
              var t=Math.abs(y)/9;
              var r=Math.round(40+t*80);
              var g=Math.round(230-t*100);
              var b=Math.round(220-t*80);
              return 'rgba('+r+','+g+','+b+',0.85)';
            }

            switch(TL.mode){

              case 0:{ /* biconvexe */
                var xc1=Math.sqrt(R1*R1-d*d);
                var xc2=-Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2,cc=B*B+xc2*xc2-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb+Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s-xc2);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=-Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  if(mo.dia) rayLine(xdia,y1,x1s,y1,clr,false);
                  else rayLine(xmin,y1,x1s,y1,clr,false);
                  rayLine(x1s,y1,x2s,y2s,clr,false);
                  rayLine(x2s,y2s,xmax,y3,clr,false);
                  /* symétrie */
                  var i_=-i, r_=Math.asin(Math.sin(i_)/N);
                  var A_=-Math.tan(i_-r_); var B_=-y1-A_*x1s;
                  var aa_=A_*A_+1,bb_=A_*B_-xc2,cc_=B_*B_+xc2*xc2-R2*R2;
                  var disc_=bb_*bb_-aa_*cc_; if(disc_<0) continue;
                  var x2_=(-bb_+Math.sqrt(disc_))/aa_; var y2_=B_+A_*x2_;
                  var j_=Math.atan2(y2_,x2_-xc2);
                  var r2_=Math.asin(N*Math.sin(j_+i_-r_));
                  var A2_=-Math.tan(r2_-j_);
                  var y3_=A2_*(xmax-x2_)+y2_;
                  if(mo.dia) rayLine(xdia,-y1,x1s,-y1,clr,false);
                  else rayLine(xmin,-y1,x1s,-y1,clr,false);
                  rayLine(x1s,-y1,x2_,y2_,clr,false);
                  rayLine(x2_,y2_,xmax,y3_,clr,false);
                }
                break;}

              case 1:{ /* plan-convexe 1 */
                var xc2v=-(Math.sqrt(R2*R2-d*d));
                for(var ri=1;ri<=TL.nb;ri++){
                  var y2=ri*1.5;
                  var X2s=Math.sqrt(R2*R2-y2*y2);
                  var x2s=X2s+xc2v;
                  var clr=rayColor(y2);
                  var i=Math.atan2(y2,X2s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=-Math.tan(r-i);
                  var y3=A*(xmax-x2s)+y2;
                  rayLine(xdia,y2,x2s,y2,clr);
                  rayLine(x2s,y2,xmax,y3,clr);
                  rayLine(xdia,-y2,x2s,-y2,clr);
                  rayLine(x2s,-y2,xmax,-y3,clr);
                }
                break;}

              case 2:{ /* plan-convexe 2 */
                var xc1v=Math.sqrt(R1*R1-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1);
                  var x1s=xc1v-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var y2=y1-A*x1s;
                  var r2=Math.asin(N*Math.sin(i-r));
                  var A2=-Math.tan(r2);
                  var y3=A2*xmax+y2;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,0,y2,clr);
                  rayLine(0,y2,xmax,y3,clr);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,0,-y2,clr);
                  rayLine(0,-y2,xmax,-y3,clr);
                }
                break;}

              case 3:{ /* biconcave */
                var xc1b=-(R1+0.5); var xc2b=(R2+0.5);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1b+X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2b,cc=B*B+xc2b*xc2b-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var X2s=Math.sqrt(R2*R2-y2s*y2s);
                  var j=Math.atan2(y2s,X2s);
                  var r2=Math.asin(N*Math.sin(j+i-r));
                  var A2=Math.tan(r2-j);
                  var y3=A2*(xmax-x2s)+y2s;
                  var y3b=A2*(xmin-x2s)+y2s;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,x2s,y2s,clr);
                  rayLine(x2s,y2s,xmax,y3,clr);
                  /* prolongement virtuel */
                  var rc=255-Math.round(7*y1), gc=255-Math.round(15*y1);
                  rayLine(x2s,y2s,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,x2s,-y2s,clr);
                  rayLine(x2s,-y2s,xmax,-y3,clr);
                  rayLine(x2s,-y2s,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 4:{ /* plan-concave */
                var xc2c=(R2+0.5); var X2c=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=6;ri++){
                  var y1=ri*1.5; if(y1>=9) break;
                  var X1s=Math.sqrt(R2*R2-y1*y1); var x1s=xc2c-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=N*Math.asin(Math.sin(i));
                  var A=Math.tan(r-i); var B=y1-A*x1s;
                  var y3=A*xmax+B; var y3b=A*xmin+B;
                  rayLine(xmin,y1,x1s,y1,clr);
                  rayLine(x1s,y1,xmax,y3,clr);
                  var gc=255-Math.round(15*y1);
                  rayLine(x1s,y1,xmin,y3b,'rgba(255,'+gc+',0,0.45)',true);
                  rayLine(xmin,-y1,x1s,-y1,clr);
                  rayLine(x1s,-y1,xmax,-y3,clr);
                  rayLine(x1s,-y1,xmin,-y3b,'rgba(255,'+gc+',0,0.45)',true);
                }
                break;}

              case 5:{ /* ménisque convergent */
                var xc1m=Math.sqrt(R1*R1-d*d); var xc2m=Math.sqrt(R2*R2-d*d);
                for(var ri=1;ri<=TL.nb;ri++){
                  var y1=ri*1.5;
                  var X1s=Math.sqrt(R1*R1-y1*y1); var x1s=xc1m-X1s;
                  var clr=rayColor(y1);
                  var i=Math.atan2(y1,X1s);
                  var r=Math.asin(Math.sin(i)/N);
                  var A=-Math.tan(i-r); var B=y1-A*x1s;
                  var aa=A*A+1,bb=A*B-xc2m,cc=B*B+xc2m*xc2m-R2*R2;
                  var disc=bb*bb-aa*cc; if(disc<0) continue;
                  var x2s=(-bb-Math.sqrt(disc))/aa; var y2s=B+A*x2s;
                  var j=Math.atan2(y2s,x2s+xc2m);
                  var r2=Math.asin(N*Math.sin(j-i+r));
                  var A2=-Math.tan(j-r2);
                  var y3=A2*(xmax-x2s)+y2s;
                  rayLine(xdia,y1,x1s,y1,clr);rayLine(x1s,y1,x2s,y2s,clr);rayLine(x2s,y2s,xmax,y3,clr);
                  rayLine(xdia,-y1,x1s,-y1,clr);rayLine(x1s,-y1,x2s,-y2s,clr);rayLine(x2s,-y2s,xmax,-y3,clr);
                }
                break;}

              case 6:{ /* ménisque divergent */
                var xc2v2=Math.sqrt(R2*R2-d*d);
